ACCOUNTS = {101: {"owner": "alice", "balance": 500_000},
            202: {"owner": "bob", "balance": 9_000_000}}

def get_account_bad(user, account_id):      # 로그인만 확인
    return ACCOUNTS[account_id]

def get_account_good(user, account_id):     # 이 계좌가 '그 사람 것'인지 확인
    acc = ACCOUNTS.get(account_id)
    if acc is None or acc["owner"] != user:
        return {"status": 404}
    return acc

# 진단: alice 로 로그인한 채 번호만 바꿔 남의 계좌를 부른다
for fn in (get_account_bad, get_account_good):
    print(fn.__name__, fn("alice", 202))
# get_account_bad {'owner': 'bob', 'balance': 9000000}
# get_account_good {'status': 404}
